CREATE TABLE IF NOT EXISTS cache (key TEXT PRIMARY KEY, payload TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, key TEXT UNIQUE NOT NULL, url TEXT NOT NULL, platform TEXT NOT NULL, status TEXT NOT NULL, created INTEGER NOT NULL, lease INTEGER DEFAULT 0, attempts INTEGER DEFAULT 0, error TEXT);
CREATE TABLE IF NOT EXISTS limits (bucket TEXT PRIMARY KEY, n INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS health (key TEXT PRIMARY KEY, value INTEGER NOT NULL);
